Definition dsjl (W : list ivl) (l : list (Z * Z)) : Prop := Forall (fun r => disjoint_from W (fst r) (snd r)) l.
Lemma dsjl_in : forall W l a n, dsjl W l -> In (a, n) l -> disjoint_from W a n.
Proof.
